gau5(){return"\u03a4\u03b7\u03bb\u03ad\u03c6\u03c9\u03bd\u03bf (\u03c0\u03c1\u03bf\u03b1\u03b9\u03c1\u03b5\u03c4\u03b9\u03ba\u03cc)"},
gauj(){return"\u0391\u03c0\u03bf\u03b8\u03ae\u03ba\u03b5\u03c5\u03c3\u03b7 & \u03c3\u03c5\u03bd\u03ad\u03c7\u03b5\u03b9\u03b1"},
gauh(){return"\u0399\u03b4\u03b9\u03bf\u03ba\u03c4\u03ae\u03c4\u03b7\u03c2 / \u0394\u03b9\u03b5\u03c5\u03b8\u03c5\u03bd\u03c4\u03ae\u03c2"},
gaug(){return"\u03a0\u03bb\u03ae\u03c1\u03b7\u03c2 \u03c0\u03c1\u03cc\u03c3\u03b2\u03b1\u03c3\u03b7 \u2014 \u03bc\u03b5\u03bd\u03bf\u03cd, \u03c1\u03c5\u03b8\u03bc\u03af\u03c3\u03b5\u03b9\u03c2, \u03b1\u03bd\u03b1\u03c6\u03bf\u03c1\u03ad\u03c2"},
