gauf(){return"\u039c\u03cc\u03bd\u03bf \u03bf\u03b8\u03cc\u03bd\u03b7 \u03ba\u03bf\u03c5\u03b6\u03af\u03bd\u03b1\u03c2 \u2014 \u03c0\u03c1\u03bf\u03b2\u03bf\u03bb\u03ae \u03ba\u03b1\u03b9 \u03bf\u03bb\u03bf\u03ba\u03bb\u03ae\u03c1\u03c9\u03c3\u03b7 \u03c0\u03b1\u03c1\u03b1\u03b3\u03b3\u03b5\u03bb\u03b9\u03ce\u03bd"},
ga4p(){return"\u039c\u03c0\u03b1\u03c1"},
gaue(){return"\u039f\u03b8\u03cc\u03bd\u03b7 \u03ba\u03bf\u03c5\u03b6\u03af\u03bd\u03b1\u03c2 \u03c6\u03b9\u03bb\u03c4\u03c1\u03b1\u03c1\u03b9\u03c3\u03bc\u03ad\u03bd\u03b7 \u03c3\u03c4\u03bf\u03bd \u03c3\u03c4\u03b1\u03b8\u03bc\u03cc \u03c0\u03bf\u03c4\u03ce\u03bd"},
